<?php require_once __DIR__.'/config/database.php';$pageTitle='Donation';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$amount=(float)($_POST['amount']??0);$method=trim($_POST['method']??'');$trx=trim($_POST['transaction_id']??'');$message=trim($_POST['message']??'');if($name!==''&&$phone!==''&&$amount>0){$st=$pdo->prepare('INSERT INTO donations(donor_name,phone,amount,method,transaction_id,message) VALUES(?,?,?,?,?,?)');$st->execute([$name,$phone,$amount,$method,$trx,$message]);$success='আপনার Donation তথ্য গ্রহণ করা হয়েছে। যাচাই শেষে নিশ্চিত করা হবে।';}}include __DIR__.'/includes/header.php';?><section class="section soft-bg"><div class="container form-container"><div class="section-heading center"><span>Donation</span><h2>অনুদান প্রদান করুন</h2></div><?php if($success):?><div class="success"><?=htmlspecialchars($success)?></div><?php endif;?><form method="post" class="public-form"><input name="name" placeholder="আপনার নাম" required><input name="phone" placeholder="মোবাইল নাম্বার" required><input type="number" name="amount" min="1" step="0.01" placeholder="অনুদানের পরিমাণ (৳)" required><select name="method"><option>bKash</option><option>Nagad</option><option>Bank</option><option>Cash</option></select><input name="transaction_id" placeholder="Transaction ID (যদি থাকে)"><textarea name="message" placeholder="বার্তা"></textarea><button>Donation Submit করুন</button></form></div></section><?php include __DIR__.'/includes/footer.php';?>